cat > /tmp/verify.py <<'EOF'
import redis
bad=0; n=0
for db in range(16):
    a=redis.Redis(port=6379,db=db); b=redis.Redis(port=6380,db=db)
    ka=set(a.scan_iter(count=1000)); kb=set(b.scan_iter(count=1000))
    if ka!=kb: print("db",db,"keyset diff",len(ka-kb),len(kb-ka)); bad+=1
    for k in ka:
        n+=1
        t=a.type(k)
        if t!=b.type(k): print("type",db,k); bad+=1; continue
        t=t.decode()
        if t=='string': va,vb=a.get(k),b.get(k)
        elif t=='list': va,vb=a.lrange(k,0,-1),b.lrange(k,0,-1)
        elif t=='set': va,vb=a.smembers(k),b.smembers(k)
        elif t=='zset': va,vb=a.zrange(k,0,-1,withscores=True),b.zrange(k,0,-1,withscores=True)
        elif t=='hash': va,vb=a.hgetall(k),b.hgetall(k)
        elif t=='stream':
            va=(a.xrange(k),a.xinfo_stream(k)['last-generated-id'],[(g['name'],g['last-delivered-id'],g['pending'],a.xinfo_consumers(k,g['name']) and sorted(c['name'] for c in a.xinfo_consumers(k,g['name'])), a.xpending_range(k,g['name'],'-','+',100000)) for g in a.xinfo_groups(k)])
            vb=(b.xrange(k),b.xinfo_stream(k)['last-generated-id'],[(g['name'],g['last-delivered-id'],g['pending'],b.xinfo_consumers(k,g['name']) and sorted(c['name'] for c in b.xinfo_consumers(k,g['name'])), b.xpending_range(k,g['name'],'-','+',100000)) for g in b.xinfo_groups(k)])
            # delivery times/idle may differ slightly; compare ids/consumers/counts
            strip=lambda v:(v[0],v[1],[(g[0],g[1],g[2],g[3],[(p['message_id'],p['consumer'],p['times_delivered']) for p in g[4]]) for g in v[2]])
            va,vb=strip(va),strip(vb)
        else: va,vb=a.dump(k),b.dump(k); print("other type",t,k)
        if va!=vb: print("value",db,k,t); bad+=1
        ta,tb=a.pttl(k),b.pttl(k)
        if (ta<0)!=(tb<0) or abs(ta-tb)>5000: print("ttl",db,k,ta,tb); bad+=1
print("keys",n,"bad",bad)
EOF
python3 /tmp/verify.py
